            gas,
            rentalType: cState.rentalType,
            usesTimesRental,
            timesDistanceFee,
            movementAmount,
            movementType,
            movementBaseType,
            extras,
            splitExtras,
            clubExtras,
            reward: rewardAmount,
            rawPay,
            splitPay,
            clubPay,
            splitRound,
            clubRound,
            totalPay,
            driverRound
